const deal = $('Extract Contract Terms').item.json.data;
const advice = $input.first().json.markdown;
const fileName = $('New Contract Uploaded').item.json.name;

// --- Red flag analysis ---
const redFlags = deal.redFlags || [];
const highRisks = redFlags.filter(r => r.severity === 'High');
const mediumRisks = redFlags.filter(r => r.severity === 'Medium');
const lowRisks = redFlags.filter(r => r.severity === 'Low');

let riskLevel = 'Low';
if (highRisks.length >= 2) riskLevel = 'High';
else if (highRisks.length === 1 || redFlags.length >= 3) riskLevel = 'Medium';

// --- Compensation ---
const comp = deal.compensation || {};
const totalRate = comp.totalRate || 0;
const rateType = (comp.rateType || 'not_specified').replace(/_/g, ' ');
const paymentTerms = comp.paymentSchedule || 'Not specified';
const paymentDays = comp.paymentTermDays || 0;
const killFee = comp.killFee || 'None specified';
const expenseReimbursement = comp.expenseReimbursement || 'Not specified';

// --- Deliverables ---
const deliverables = deal.deliverables || [];
const deliverableSummary = deliverables.length > 0
  ? deliverables.map(d => `${d.quantity || 1}x ${d.type} (${d.platform || 'unspecified'})`).join(', ')
  : 'Not specified';
const totalDeliverableCount = deliverables.reduce((sum, d) => sum + (d.quantity || 1), 0);
const effectivePerDeliverable = totalDeliverableCount > 0 ? Math.round(totalRate / totalDeliverableCount) : 0;

const platforms = deal.platforms && deal.platforms.length > 0
  ? deal.platforms.join(', ')
  : 'Not specified';

// --- Content rights ---
const ownership = (deal.contentOwnership || 'not_specified').replace(/_/g, ' ');
const usageRights = deal.usageRights || {};
const usageDuration = usageRights.duration || 'Not specified';
const usageChannels = usageRights.channels && usageRights.channels.length > 0
  ? usageRights.channels.join(', ')
  : 'Not specified';
const brandCanEdit = usageRights.canEdit ? 'Yes' : 'No';
const brandCanSublicense = usageRights.canSublicense ? 'Yes' : 'No';

// --- Whitelisting ---
const wl = deal.whitelisting || {};
let whitelistSummary = 'None';
if (wl.allowed) {
  whitelistSummary = `${wl.duration || 'No time limit'}`;
  if (wl.spendCap && wl.spendCap !== 'Not specified') whitelistSummary += ` / Cap: ${wl.spendCap}`;
  else whitelistSummary += ' / No spend cap';
}

// --- Exclusivity ---
const excl = deal.exclusivity || {};
let exclusivitySummary = 'None';
if (excl.hasExclusivity) {
  exclusivitySummary = `${excl.window || 'Duration not specified'}`;
  if (excl.scope) exclusivitySummary += ` — Scope: ${excl.scope}`;
  if (excl.postCampaignDays) exclusivitySummary += ` (${excl.postCampaignDays} days post-campaign)`;
}

// --- Non-compete ---
const nc = deal.nonCompete || {};
let nonCompeteSummary = 'None';
if (nc.hasNonCompete) {
  nonCompeteSummary = `${nc.duration || 'Duration not specified'}`;
  if (nc.scope) nonCompeteSummary += ` — ${nc.scope}`;
}

// --- Morality clause ---
const moral = deal.moralityClause || {};
let moralitySummary = 'None';
if (moral.exists) {
  moralitySummary = `${moral.subjectivity || 'Unknown'} subjectivity`;
  if (moral.triggers) moralitySummary += ` — Triggers: ${moral.triggers}`;
}

// --- Likeness ---
const lik = deal.likeness || {};
let likenessSummary = 'Not granted';
if (lik.granted) {
  likenessSummary = `${lik.duration || 'No time limit'}`;
  if (lik.scope) likenessSummary += ` — ${lik.scope}`;
}

// --- Termination ---
const term = deal.terminationRights || {};
const creatorCanTerminate = term.creatorCanTerminate ? 'Yes' : 'No';
const ftcCompliance = deal.ftcCompliance ? 'Yes' : 'No / Not mentioned';
const latePaymentPenalty = deal.latePaymentPenalty || 'None specified';
const revisionLimit = deal.revisionLimit || 'Not specified';
const approvalProcess = deal.approvalProcess || 'Not specified';

// --- Format red flags for sheets ---
const flagsSummary = redFlags.length > 0
  ? redFlags.map(r => `[${r.severity}] ${r.issue}`).join('; ')
  : 'None identified';

// Top negotiation points (from high-severity flags)
const negotiationPoints = redFlags
  .filter(r => r.severity === 'High' || r.severity === 'Medium')
  .map(r => `${r.issue}: ${r.whyItMatters || ''}`)
  .join(' | ') || 'Contract looks reasonable';

// Truncate advice for sheets
const adviceShort = advice && advice.length > 1000
  ? advice.substring(0, 1000) + '...'
  : advice;

return [{
  json: {
    // Identity
    brandName: deal.brandName || 'Not specified',
    campaignName: deal.campaignName || 'Not specified',
    creatorName: deal.creatorName || 'Not specified',
    campaignStart: deal.campaignStart || '',
    campaignEnd: deal.campaignEnd || '',

    // Money
    totalRate: totalRate,
    rateType: rateType,
    effectivePerDeliverable: effectivePerDeliverable,
    paymentTerms: paymentTerms,
    paymentDays: paymentDays,
    killFee: killFee,
    expenseReimbursement: expenseReimbursement,

    // Scope
    deliverables: deliverableSummary,
    totalDeliverableCount: totalDeliverableCount,
    platforms: platforms,
    revisionLimit: revisionLimit,
    approvalProcess: approvalProcess,

    // Rights
    contentOwnership: ownership,
    usageDuration: usageDuration,
    usageChannels: usageChannels,
    brandCanEdit: brandCanEdit,
    brandCanSublicense: brandCanSublicense,
    whitelisting: whitelistSummary,
    likeness: likenessSummary,

    // Restrictions
    exclusivity: exclusivitySummary,
    nonCompete: nonCompeteSummary,
    nonDisparagement: deal.nonDisparagement ? 'Yes' : 'No',
    moralityClause: moralitySummary,

    // Protections
    creatorCanTerminate: creatorCanTerminate,
    ftcCompliance: ftcCompliance,
    latePaymentPenalty: latePaymentPenalty,
    indemnification: deal.indemnification || 'Not specified',
    disputeResolution: deal.disputeResolution || 'Not specified',
    autoRenewal: deal.autoRenewal ? 'Yes' : 'No',

    // Risk
    redFlagCount: redFlags.length,
    highRiskCount: highRisks.length,
    mediumRiskCount: mediumRisks.length,
    flagsSummary: flagsSummary,
    riskLevel: riskLevel,
    negotiationPoints: negotiationPoints,

    // Advice
    creatorAdvice: advice,
    creatorAdviceShort: adviceShort,

    // Meta
    fileName: fileName,
    fileId: $('New Contract Uploaded').item.json.id,
    processedAt: new Date().toISOString()
  }
}];

